use forge_domain :: Transformer ; use crate :: dto :: openai :: { Request , ThinkingConfig , ThinkingType } ; use pretty_assertions :: assert_eq ; use super :: * ; # [doc = " Transformer that converts standard ReasoningConfig to z.ai's thinking format"] # [doc = ""] # [doc = " Z.ai providers require reasoning to be set as `\"thinking\": {\"type\":"] # [doc = " \"enabled\"}` while the codebase uses OpenAI's `reasoning` field with"] # [doc = " ReasoningConfig structure. This transformer maps the standard reasoning"] # [doc = " configuration to z.ai's format."] # [doc = ""] # [doc = " # Transformation Rules"] # [doc = ""] # [doc = " - If `reasoning.enabled == Some(true)` → `thinking = {\"type\": \"enabled\"}`"] # [doc = " - If `reasoning.enabled == Some(false)` → `thinking = {\"type\": \"disabled\"}`"] # [doc = " - If `reasoning` is None or `enabled` is None → no `thinking` field added"] # [doc = " - Original `reasoning` field is removed after transformation"] # [doc = ""] # [doc = " # Note"] # [doc = ""] # [doc = " Z.ai only supports enabled/disabled state. Other ReasoningConfig fields"] # [doc = " (`max_tokens`, `effort`, `exclude`) are ignored as they are not supported by"] # [doc = " z.ai's API."] pub struct SetZaiThinking ;